@startuml

interface User {
  + full_name : string
  + borrow_history : Borrow[]
}

class Under_aged implements User {
  + student_card : string
}

class Adult implements User {
  + id_card : string
}

class Borrow {
  + date : date
}

class Book {
  + title : string
  + author : string
}

class Library {
  + books : Book[]
}

User "1" -- "*" Borrow : has history
Borrow "*" -- "1" Book : refers to
User "0..1" -- "0..4" Book : borrows
Library "1" *-- "*" Book : contains

@enduml

